import{z as i,x as l,o as e,c as s,q as r,j as t,D as E,d as o,s as n,S as A}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"保留工资与搜寻时长","description":"","frontmatter":{"title":"保留工资与搜寻时长","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/reservation-wage-search.md","filePath":"econ/reservation-wage-search.md","lastUpdated":1791063341000}'),_={name:"econ/reservation-wage-search.md"};function p(d,a,c,h,F,m){const B=l("Mermaid");return e(),s("div",null,[a[2]||(a[2]=r('<h1 id="保留工资与搜寻时长" tabindex="-1">保留工资与搜寻时长 <a class="header-anchor" href="#保留工资与搜寻时长" aria-label="Permalink to &quot;保留工资与搜寻时长&quot;">​</a></h1><div class="epigraph"><p>最优求职策略简单得像一道门槛：低于它的出价一律拒绝，高于它的当即接受；门槛随失业期间的资产价值移动，搜寻时长随之改变。</p><footer>—— McCall, Economics of Information and Job Search, QJE 1970</footer></div><p><a href="/econ/unemployment-stock-flow">上一课</a>把失业写成流量水位：入职率 \\(f\\) 是爬岸的速度，且美国周期的波动主要出在这一侧。本课的缺口是 \\(f\\) 的工人侧：失业者面对的是一条到来的出价流，每个出价要决定接受还是再等。宏观的<a href="/econ/ui-moral-hazard">失业保险课</a>已给出 Baily–Chetty 的最优替代率，但把持续时间弹性当外生输入；本课给这个弹性一个结构来源——保留工资。市场侧的接触率由<a href="/econ/search-matching-dmp">搜寻匹配</a>的匹配函数给出，本课不再写。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>搜寻是有成本的信息采集：每期花成本、抽一个来自分布 \\(F\\) 的出价 \\(w\\)，接受则就业，拒绝拿失业流 \\(b\\)（失业保险加家庭生产的价值）、下期再抽。逐个比较「这个出价好还是等下一个好」会陷入无穷回归。McCall 的做法是把决策压成一个数：保留工资 \\(w_r\\)，定义为「接受」与「再等一期」的无差异点：</p> \\[w_r \\;=\\; b \\;+\\; \\frac{\\beta}{1-\\beta}\\int_{w_r}^{\\infty}\\bigl(w-w_r\\bigr)\\,dF(w). \\]<p>右端第二项是「再等」的期权价值：它收出价分布的上尾。于是规则只是一道门槛：\\(w \\geq w_r\\) 接受，否则拒绝。比较静态跟着写下：\\(b\\) 上升（给付更高）、出价分布一阶改善、贴现更耐心，\\(w_r\\) 上升；搜寻成本上升，\\(w_r\\) 下降。</p><p><span class="marginnote">术语翻译：「再等的期权价值」——拒绝当前出价不是白白干等，而是花一期的搜寻成本，买一张「下期再抽一次」的彩票。出价分布的上尾越厚（抽到高工资的机会越大），这张彩票越值钱，\\(w_r\\) 就被抬得越高。</span></p>',8)),(e(),t(A,null,{default:E(()=>[n(B,{id:"mermaid-20",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22%E5%A4%B1%E4%B8%9A%E6%B5%81%20b%EF%BC%9A%E4%BF%9D%E9%99%A9%20%2B%20%E5%AE%B6%E5%BA%AD%E7%94%9F%E4%BA%A7%22%5D%20--%3E%20WR%5B%22%E4%BF%9D%E7%95%99%E5%B7%A5%E8%B5%84%20w_r%22%5D%0A%20%20F%5B%22%E5%87%BA%E4%BB%B7%E5%88%86%E5%B8%83%20F%22%5D%20--%3E%20WR%0A%20%20WR%20--%3E%20ACC%5B%22%E6%8E%A5%E5%8F%97%E7%8E%87%201%20%E2%88%92%20F(w_r)%22%5D%0A%20%20ACC%20--%3E%20DUR%5B%22%E6%9C%9F%E6%9C%9B%E6%90%9C%E5%AF%BB%E6%97%B6%E9%95%BF%22%5D%0A%20%20DUR%20--%3E%20UF%5B%22%E5%85%A5%E8%81%8C%E7%8E%87%20f%20%E4%B8%8E%E7%A8%B3%E6%80%81%20u*%22%5D%0A%20%20B%20--%3E%20NOTE%5B%22UI%20%E5%BB%B6%E9%95%BF%20%E2%86%92%20b%E2%86%91%20%E2%86%92%20%E6%97%B6%E9%95%BF%E2%86%91%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p><span class="marginnote">若每期恰有一次出价机会，期望搜寻时长是 \\(1/(1-F(w_r))\\)：门槛抬一点，时长不是线性地长，而是按门槛处的密度倒数放大——上尾薄的市场里，\\(w_r\\) 的微小移动就画出很长的失业。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把上一课的 \\(f\\) 拆开：入职率 \\(=\\) 接触率 \\(\\times\\) 接受率 \\(1-F(w_r)\\)。失业保险改的是第二项。模型预言给付更高、期限更长，实证要回答量级与机制。Meyer 1990 用行政数据发现：退出失业的风险率在给付用尽前几周骤升、用尽后回落——激励是真实起作用的，而尖峰位置钉在制度参数上。Katz–Meyer 1990 把尖峰的一部分归给召回预期，量级要打折。准实验侧：Card–Levine 2000 用新泽西的延付改革，大衰退中 Rothstein 2011 评估大规模延长——方向都是正的（延长给付拉长时长），但量级温和：潜在期限大幅延长，平均时长只多出几周。</p><p>分歧在解释。一类读法是道德风险：补贴让等待变便宜，是福利损失。另一类是<a href="/econ/ui-moral-hazard">失业保险课</a>引的 Chetty 2008：有资产的失业者时长更长，一部分是流动性放松后的最优等待，不一定是浪费——「更长」可以是买到了更好的匹配。区分二者要资产数据，不是时长回归能给的。</p><p><span class="marginnote">术语翻译：「风险率」就是「撑到这一周还没找到工作的人，在这一周内找到工作的概率」。Meyer 的发现读出来就是：临近救济金用尽，这个概率骤然抬升、用尽后又回落——制度日历直接写进了个体行为，激励是真实的。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>模型把时长只写在一根管道上：拒绝更多出价。真实失业者还有第二根：搜寻努力（投多少简历、跑几场面试）本身不可观测，也会随给付下降。保留工资管道在 McCall 里可测可算，努力管道才是道德风险的真正藏身处；两根管道对政策的反应不同——延长期限主要动前者，替代率主要动后者，混着读会得出「给付无关紧要」的错误归因。</p>',7)),(e(),t(A,null,{default:E(()=>[n(B,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%BB%B6%E9%95%BF%E7%BB%99%E4%BB%98%E6%9C%9F%E9%99%90%22%5D%20--%3E%20C%5B%22%E4%BF%9D%E7%95%99%E5%B7%A5%E8%B5%84%E7%AE%A1%E9%81%93%EF%BC%9Aw_r%20%E4%B8%8A%E5%8D%87%E3%80%81%E6%8B%92%E7%BB%9D%E6%9B%B4%E5%A4%9A%E5%87%BA%E4%BB%B7%22%5D%0A%20%20B%5B%22%E6%8F%90%E9%AB%98%E6%9B%BF%E4%BB%A3%E7%8E%87%22%5D%20--%3E%20C%0A%20%20B%20--%3E%20D%5B%22%E5%8A%AA%E5%8A%9B%E7%AE%A1%E9%81%93%EF%BC%9A%E6%8A%95%E7%AE%80%E5%8E%86%E4%B8%8E%E9%9D%A2%E8%AF%95%E6%AC%A1%E6%95%B0%E5%87%8F%E5%B0%91%22%5D%0A%20%20C%20--%3E%20E%5B%22%E5%8F%AF%E8%A7%82%E6%B5%8B%EF%BC%9A%E6%97%B6%E9%95%BF%E4%B8%8E%E6%8E%A5%E5%8F%97%E5%B7%A5%E8%B5%84%E7%9A%84%E5%88%86%E5%B8%83%22%5D%0A%20%20D%20--%3E%20F%5B%22%E4%B8%8D%E5%8F%AF%E8%A7%82%E6%B5%8B%EF%BC%9A%E9%81%93%E5%BE%B7%E9%A3%8E%E9%99%A9%E7%9A%84%E7%9C%9F%E6%AD%A3%E8%97%8F%E8%BA%AB%E5%A4%84%22%5D%0A%20%20E%20--%3E%20G%5B%22%E5%8F%AA%E7%9C%8B%E6%97%B6%E9%95%BF%E7%9A%84%E5%9B%9E%E5%BD%92%E4%BC%9A%E6%B7%B7%E5%90%8C%E4%B8%A4%E6%A0%B9%E7%AE%A1%E9%81%93%22%5D%0A%20%20F%20--%3E%20G%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<p><span class="marginnote">常见误区：初学者容易以为领保险的人只是「挑工作更挑」；实际上给付还压低搜寻努力本身——投几份简历、跑几场面试是私下信息，雇主与统计都看不见。真正的道德风险藏在努力管道里，而保留工资管道反而是可测、可算的那一根。</span></p><p><span class="marginnote">直觉类比：寒流来了海里的鱼整体变少（分布 \\(F\\) 左移），渔夫「三斤以下不放筐」的标准没动，空网的天数照样拉长。把失业变长全归成「工人变挑」，就像把空网归成「渔夫变贪」——是分布动了，不是门槛动了。</span></p><p>模型还预言 \\(w_r\\) 随失业累积而降（技能折旧、资格耗尽），实测的保留工资却降得慢、且报告值普遍偏高——被访者报的是「可接受」而非「最优门槛」。这提醒：保留工资是模型里的决策变量，不是可直接读的测量。错在哪：拿模型参数直接当问卷条目，或反过来拿问卷否定模型——两者都把决策变量与测量当同一件东西。与上一课合起来：制度（给付水平与期限）改 \\(w_r\\)，\\(w_r\\) 改接受率，接受率改 \\(f\\)，\\(f\\) 改稳态水位——这就是「失业、搜寻与制度」这个单元的因果链，后面的买方垄断与最低工资都在这条链上加环节。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>基准假设出价分布 \\(F\\) 不随个人状态移动；衰退里 \\(F\\) 整体左移，\\(w_r\\) 的比较静态不能照搬，否则会把「好岗变少」误算成「工人变挑」。模型还假设出价是独立抽取，忽略搜寻的定向与配对——那是 DMP 的对象。本课不做最优保险的福利计算，Baily–Chetty 的权衡与充分统计公式已在<a href="/econ/ui-moral-hazard">保险课</a>给出，这里只供给它的行为参数。长期失业对 \\(w_r\\) 的反馈（折旧、污名）也只点到为止。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>McCall 把序贯搜寻压成门槛规则：\\(w_r = b + \\frac{\\beta}{1-\\beta}\\int (w-w_r)\\,dF\\)。</li><li>失业保险抬高 \\(w_r\\)、拉长时长；给付用尽前的风险尖峰说明激励真实。</li><li>延长的量级温和（Rothstein 2011）；道德风险与流动性要分开（Chetty 2008）。</li><li>\\(w_r\\) 决定接受率，从而接入上一课的 \\(f\\) 与稳态水位。</li><li>出处：McCall, QJE 1970；Meyer, Econometrica 1990；Katz–Meyer 1990；Card–Levine 2000；Rothstein, BPEA 2011。</li></ul>',7))])}const D=i(_,[["render",p]]);export{f as __pageData,D as default};
